                i = 1;
                while (i < len && descriptor.charAt(i) != ')') {
                    c = descriptor.charAt(i);
                    if (c == 'L') {
                        // Object type, find ';'
                        i++;
                        while (i < len && descriptor.charAt(i) != ';') {
                            i++;
                        }
                        if (i < len) {
                            i++; // skip ';'
