protected GraphPath<V, E> edgeSetToTour(Set<E> tour, Graph<V, E> graph) {
    if (tour == null || graph == null) {
        throw new IllegalArgumentException("Tour and graph must not be null");
    }
    if (tour.isEmpty()) {
        return new GraphPathImpl<>(graph, null, null, 0.0, new ArrayList<>());
    }

    // Build adjacency list from the tour edges
    Map<V, List<E>> adjacency = new HashMap<>();
    for (E edge : tour) {
        V source = graph.getEdgeSource(edge);
        V target = graph.getEdgeTarget(edge);
        adjacency.computeIfAbsent(source, k -> new ArrayList<>()).add(edge);
        adjacency.computeIfAbsent(target, k -> new ArrayList<>()).add(edge);
    }

    // Find a starting vertex (any vertex with degree 1, or any vertex if all have degree 2)
    V start = null;
    for (V vertex : graph.getVertexSet()) {
        List<E> edges = adjacency.get(vertex);
        if (edges != null && edges.size() == 1) {
            start = vertex;
            break;
        }
    }
    if (start == null) {
        // All vertices have degree 2, pick any vertex
        start = graph.getVertexSet().iterator().next();
    }

    // Build the path by traversing the tour
    List<E> pathEdges = new ArrayList<>();
    V current = start;
    V previous = null;
    Set<E> visitedEdges = new HashSet<>();

    while (true) {
        List<E> edges = adjacency.get(current);
        if (edges == null || edges.isEmpty()) {
            break;
        }

        E nextEdge = null;
        for (E edge : edges) {
            if (!visitedEdges.contains(edge)) {
                nextEdge = edge;
                break;
            }
        }

        if (nextEdge == null) {
            break;
        }

        visitedEdges.add(nextEdge);
        pathEdges.add(nextEdge);

        V next = graph.getEdgeSource(nextEdge).equals(current) ? graph.getEdgeTarget(nextEdge) : graph.getEdgeSource(nextEdge);
        previous = current;
        current = next;

        // If we've returned to the start and visited all edges, we're done
        if (current.equals(start) && visitedEdges.size() == tour.size()) {
            break;
        }
    }

    // Calculate total weight
    double totalWeight = 0.0;
    for (E edge : pathEdges) {
        totalWeight += graph.getEdgeWeight(edge);
    }

    return new GraphPathImpl<>(graph, start, current, totalWeight, pathEdges);
}

