private Pair<List<Integer>, Long> computeSuffixSum(List<Integer> bounds) {
    if (bounds == null) {
        throw new IllegalArgumentException("bounds must not be null");
    }
    int n = bounds.size();
    List<Integer> suffixSum = new ArrayList<>(n);
    long totalSum = 0;
    long runningSum = 0;
    for (int i = n - 1; i >= 0; i--) {
        Integer val = bounds.get(i);
        if (val == null) {
            throw new IllegalArgumentException("bounds contains null element at index " + i);
        }
        runningSum += val;
        suffixSum.add(0, (int) runningSum);
    }
    totalSum = runningSum;
    return new Pair<>(suffixSum, totalSum);
}

