public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
        if (u == null) {
            throw new IllegalArgumentException("URI must not be null");
        }
        String path = u.getPath();
        if (path == null || path.isEmpty()) {
            return new ArrayList<>();
        }
        // If the path is an absolute path, ignore the leading '/'
        if (path.startsWith("/")) {
            path = path.substring(1);
        }
        if (path.isEmpty()) {
            return new ArrayList<>();
        }
        String[] segments = path.split("/", -1);
        List<PathSegmentImpl> result = new ArrayList<>();
        for (String segment : segments) {
            if (segment.isEmpty()) {
                continue;
            }
            if (decode) {
                try {
                    segment = URLDecoder.decode(segment, "UTF-8");
                } catch (UnsupportedEncodingException e) {
                    // UTF-8 is always supported, so this should not happen
                    throw new RuntimeException("UTF-8 encoding not supported", e);
                }
            }
            result.add(new PathSegmentImpl(segment));
        }
        return result;
    }

