public static String applyRelativePath(String path, String relativePath) {
        if (path == null || relativePath == null) {
            throw new IllegalArgumentException("Path and relative path must not be null");
        }

        // Normalize the base path: ensure it ends with a separator if it's a directory
        // We'll treat the base path as a directory path
        String normalizedPath = path;
        if (!normalizedPath.endsWith("/") && !normalizedPath.isEmpty()) {
            normalizedPath = normalizedPath + "/";
        }

        // Handle the relative path
        String result = normalizedPath + relativePath;

        // Normalize the result: resolve "." and ".." segments
        String[] parts = result.split("/");
        java.util.Deque<String> stack = new java.util.ArrayDeque<>();

        for (String part : parts) {
            if (part.isEmpty() || part.equals(".")) {
                continue;
            } else if (part.equals("..")) {
                if (!stack.isEmpty()) {
                    stack.pop();
                }
            } else {
                stack.push(part);
            }
        }

        // Reconstruct the path
        StringBuilder sb = new StringBuilder();
        // If the original path started with "/", we should preserve that
        boolean isAbsolute = path.startsWith("/");
        if (isAbsolute) {
            sb.append("/");
        }

        // The stack is in reverse order (last pushed is first)
        java.util.List<String> reversed = new java.util.ArrayList<>(stack);
        java.util.Collections.reverse(reversed);

        for (int i = 0; i < reversed.size(); i++) {
            if (i > 0) {
                sb.append("/");
            }
            sb.append(reversed.get(i));
        }

        // If the result is empty and the path was absolute, return "/"
        if (sb.length() == 0) {
            return isAbsolute ? "/" : "";
        }

        return sb.toString();
    }

