protected void subAppend(LoggingEvent event) {
    try {
        // Get the message from the logging event
        String message = event.getRenderedMessage();
        if (message == null) {
            message = "";
        }

        // Get the timestamp
        long timestamp = event.getTimeStamp();

        // Get the thread name
        String threadName = event.getThreadName();

        // Get the level
        String level = event.getLevel().toString();

        // Get the logger name
        String loggerName = event.getLoggerName();

        // Get the throwable information if any
        String throwableInfo = "";
        Throwable throwable = event.getThrowable();
        if (throwable != null) {
            java.io.StringWriter sw = new java.io.StringWriter();
            throwable.printStackTrace(new java.io.PrintWriter(sw));
            throwableInfo = sw.toString();
        }

        // Format the log entry
        String logEntry = String.format("%d [%s] %s %s - %s%s",
                timestamp,
                threadName,
                level,
                loggerName,
                message,
                throwableInfo.isEmpty() ? "" : "\n" + throwableInfo);

        // Write the log entry to the output
        writeLogEntry(logEntry);
    } catch (Exception e) {
        // Handle any exceptions that occur during writing
        handleException(e);
    }
}

