    String dirPath;

    if (os.contains("win")) {
        // For Windows 2000, use Documents and Settings
        String userHome = System.getProperty("user.home");
        dirPath = userHome + "\\Documents and Settings\\lf5";
    } else {
        // For other platforms, use user.home
        String userHome = System.getProperty("user.home");
        dirPath = userHome + "/lf5";
    }

    File dir = new File(dirPath);
    if (!dir.exists()) {
        if (!dir.mkdirs()) {
            throw new RuntimeException("Failed to create directory: " + dirPath);
        }
    }
}

