public long readRawVarint64() throws IOException {
        int shift = 0;
        long result = 0;
        while (true) {
            if (shift == 64) {
                throw new IOException("varint too long");
            }
            int b = read();
            if (b == -1) {
                throw new EOFException();
            }
            if ((b & 0x80) == 0) {
                result |= ((long) b) << shift;
                return result;
            } else {
                result |= ((long) (b & 0x7F)) << shift;
                shift += 7;
            }
        }
    }

